package fr.geotower.data.db

/** Localized meanings for the columns in the installed GeoTower database schemas. */
object DatabaseColumnGlossary {
    private data class Meaning(
        val fr: String,
        val en: String,
        val de: String,
        val es: String,
        val it: String,
        val pt: String,
    ) {
        fun inLanguage(language: String): String = when (language.lowercase()) {
            "fr" -> fr
            "de" -> de
            "es" -> es
            "it" -> it
            "pt" -> pt
            else -> en
        }
    }

    private data class ColumnKey(
        val database: InspectableDatabase,
        val table: String,
        val column: String,
    )

    private fun meaning(fr: String, en: String, de: String, es: String, it: String, pt: String) =
        Meaning(fr, en, de, es, it, pt)

